function importedModules(source) {
  const found = new Set();
  for (const line of source.split("\n")) {
    const m = /^\s*import\b[^\n]*?\bfrom\s+["']([^"']+)["']/.exec(line);
    if (m) found.add(m[1]);
  }
  return [...found].sort();
}

